// Genereras av kallor-kemi/omrade4/exportsite.py (sajtkonv.py, latt_ov.py) – ändra inte för hand.
// Kemi område 4: varje moment i tre nivåer (lättläst, grundtext, fördjupning), skrivet för skärm i sajtens vanliga sidformat. Elevversion, utan facit. Lättläst har interaktiva övningar.
var innehall = window.innehall || {};
innehall["kemi-m-4-1-1"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Vad händer när atomer möts?", "text": ["<p>Atomer sitter ofta ihop med andra atomer. Då bildas en <strong>kemisk förening</strong>. Vatten och bordssalt är exempel.</p>", "<p>Det som håller ihop atomerna kallas <strong>kemisk bindning</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_oversikt.png\" alt=\"\"></figure>", "<p>Atomer kan <strong>dela</strong> elektroner. Då bildas molekyler.</p>", "<p>Elektroner kan också <strong>flytta</strong> från en atom till en annan. Då bildas joner.</p>", "<p>I en <strong>kemisk reaktion</strong> byter atomerna partner. Nya ämnen bildas. Inga atomer försvinner.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Atomer sitter ihop med bindningar. I en kemisk reaktion bildas nya ämnen.</div>"]}, {"ikon": "✏️", "titel": "Öva: Vad händer när atomer möts?", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad håller ihop atomer?", "val": ["Kemiska bindningar", "Magneter", "Lim"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Vatten är en kemisk förening.", "Atomer försvinner i en kemisk reaktion.", "I en kemisk reaktion bildas nya ämnen."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["bindning", "delar", "flyttar"], "meningar": ["Atomer kan § elektroner.", "Elektroner kan också § till en annan atom.", "Det som håller ihop atomer kallas kemisk §."], "ratt": ["delar", "flyttar", "bindning"]}, {"typ": "skriv", "fraga": "Nämn en kemisk förening du känner till.", "borja": "En kemisk förening är", "forslag": "Till exempel vatten eller bordssalt."}]}, {"ikon": "📖", "titel": "Molekyler och kovalent bindning", "text": ["<p>I en <strong>kovalent bindning</strong> delar atomer elektroner. Det sker mellan icke-metaller.</p>", "<p>Atomer som sitter ihop på det sättet bildar en <strong>molekyl</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_kovalent.png\" alt=\"\"></figure>", "<p>Exempel: vatten H₂O har 2 väteatomer och 1 syreatom. Koldioxid CO₂ har 1 kolatom och 2 syreatomer. Metan CH₄ har 1 kolatom och 4 väteatomer.</p>", "<p><strong>Molekylformeln</strong> visar vilka atomer som finns och hur många.</p>", "<p>Väte vill ha 1 bindning, syre 2 och kol 4.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Kovalent bindning: atomer delar elektroner. Atomerna bildar en molekyl.</div>"]}, {"ikon": "✏️", "titel": "Öva: Molekyler och kovalent bindning", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad händer i en kovalent bindning?", "val": ["Atomer delar elektroner", "Elektroner flyttar", "Atomer försvinner"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["H₂O har två väteatomer.", "CO₂ har två kolatomer.", "En molekyl har atomer som sitter ihop."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["kolatom", "syreatom", "väteatomer"], "meningar": ["CH₄ har en § och fyra väteatomer.", "H₂O har två § och en syreatom.", "CO₂ har en § och två syreatomer."], "ratt": ["kolatom", "väteatomer", "kolatom"]}, {"typ": "skriv", "fraga": "Vad betyder molekylformeln H₂O?", "borja": "H₂O betyder", "forslag": "Två väteatomer och en syreatom."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Vad händer när atomer möts?", "text": ["<p>I kapitel 3 lärde du dig att allt består av atomer och att det är elektronerna i yttersta skalet, <strong>valenselektronerna</strong>, som avgör hur ett ämne reagerar. Nu ser vi vad som händer när atomer möts. Atomer finns sällan ensamma. De flesta ämnen du känner till är <strong>kemiska föreningar</strong>: ämnen där atomer av olika grundämnen är bundna till varandra. Vatten (H₂O), koldioxid (CO₂) och bordssalt (NaCl) är exempel.</p>", "<p>Atomerna hålls ihop av <strong>kemiska bindningar</strong>. I den förenklade modell vi använder finns två huvudsorter. I en <strong>kovalent bindning</strong> delar atomerna elektroner. I en <strong>jonbindning</strong> flyttar elektroner från en atom till en annan, så att atomerna blir laddade och dras till varandra.</p>", "<p>I en <strong>kemisk reaktion</strong> bryts bindningar och nya bildas, så att nya ämnen uppstår. Atomerna är desamma före och efter, men de sitter ihop på ett nytt sätt. Därför kan inga atomer försvinna.</p>", "<p>I det här kapitlet svarar vi på tre frågor:</p>", "<ul><li>Hur binds atomer ihop, och hur påverkar det ämnets egenskaper?</li><li>Hur vet man att en kemisk reaktion har skett, och hur skriver man den?</li><li>Vad avgör hur fort en reaktion går och om den avger eller tar upp energi?</li></ul>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Bordssalt är gjort av natrium, en metall som reagerar kraftigt med vatten, och klor, en grön gas. Ändå är salt ofarligt på maten. Hur kan egenskaperna bli så olika? Skriv ner din idé.</div>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_oversikt.png\" alt=\"Bild 4.1 Tre sätt som atomer kan ordnas om: i en molekyl delar de elektroner, i en jonförening flyttar elektroner, och i en kemisk reaktion byter atomerna partner. Bilderna är schematiska.\"><figcaption><strong>Bild 4.1</strong> Tre sätt som atomer kan ordnas om: i en molekyl delar de elektroner, i en jonförening flyttar elektroner, och i en kemisk reaktion byter atomerna partner. Bilderna är schematiska.</figcaption></figure>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Delområde</th><th>Du lär dig</th></tr><tr><td><strong>4.1</strong> Molekyler och joner</td><td>Kovalent bindning och molekyler, joner och jonföreningar, och hur bindningstypen förklarar egenskaper som smältpunkt och ledningsförmåga. Labb: leder lösningar elektrisk ström?</td></tr><tr><td><strong>4.2</strong> Kemiska reaktioner</td><td>Tecken på reaktion, reaktionsformler och massans bevarande, reaktionshastighet samt energi i reaktioner. Labb: massan bevaras.</td></tr></table></div>"], "fragor": [{"f": "Vad är en kemisk förening?", "svar": "Ett ämne där atomer av olika grundämnen är bundna till varandra, till exempel vatten (H₂O) eller bordssalt (NaCl)."}, {"f": "Vilka två sorters bindningar tittar vi på i kapitlet?", "svar": "Kovalent bindning, där atomer delar elektroner, och jonbindning, där elektroner flyttar från en atom till en annan."}, {"f": "Vad händer med atomerna i en kemisk reaktion?", "svar": "Bindningar bryts och nya bildas, så atomerna sitter ihop på ett nytt sätt. Atomerna är desamma före och efter."}]}, {"ikon": "📖", "titel": "Molekyler och kovalent bindning", "text": ["<p>Många ämnen består av <strong>molekyler</strong>: grupper av atomer som hålls ihop av <strong>kovalenta bindningar</strong>. I en kovalent bindning <em>delar</em> två atomer ett eller flera par av elektroner. Sådana bindningar bildas oftast mellan icke-metaller.</p>", "<p>Varför delar atomer elektroner? I vår förenklade modell vill atomerna få fullt yttersta skal, som ädelgaserna har. Väte har en elektron och behöver två (som helium). Två väteatomer kan dela varsin elektron, och då har båda två elektroner i sitt skal. Det är en vätgasmolekyl, H₂. Syre har sex valenselektroner och behöver två till. Kol har fyra och behöver fyra till.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_kovalent.png\" alt=\"Bild 4.2 Fyra molekyler (schematiskt): vätgas H₂, vatten H₂O, metan CH₄ och koldioxid CO₂. Varje blått elektronpar mellan två atomer är en bindning.\"><figcaption><strong>Bild 4.2</strong> Fyra molekyler (schematiskt): vätgas H₂, vatten H₂O, metan CH₄ och koldioxid CO₂. Varje blått elektronpar mellan två atomer är en bindning.</figcaption></figure>", "<p>I en vattenmolekyl delar syre ett elektronpar med varje väteatom. I metan delar kol ett par med var och en av fyra väteatomer. I koldioxid delar kol <em>två</em> par med varje syreatom, vilket kallas en dubbelbindning. Syrgas, O₂, har också en dubbelbindning.</p>"]}, {"ikon": "📖", "titel": "Att läsa en molekylformel", "text": ["<p><strong>Molekylformeln</strong> visar vilka grundämnen som finns och hur många atomer av varje. Den lilla siffran efter en beteckning gäller atomen framför. H₂O betyder alltså två väteatomer och en syreatom. Står det ingen siffra betyder det en atom.</p>", "<p>Antalet bindningar en atom vill ha hänger ihop med valenselektronerna: väte vill ha 1 bindning, syre 2, kväve 3 och kol 4. Det kan du använda när du bygger modeller av molekyler med modellkit, eller med tandpetare och gummibjörnar. Varje tandpetare är en bindning.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Atom</th><th>Valens-elektroner</th><th>Bindningar</th></tr><tr><td>Väte, H</td><td>1</td><td>1</td></tr><tr><td>Syre, O</td><td>6</td><td>2</td></tr><tr><td>Kväve, N</td><td>5</td><td>3</td></tr><tr><td>Kol, C</td><td>4</td><td>4</td></tr></table></div>"], "fragor": [{"f": "Vad är en molekyl?", "svar": "En grupp atomer som hålls ihop av kovalenta bindningar."}, {"f": "Vad sker i en kovalent bindning?", "svar": "Två atomer delar ett eller flera par av elektroner."}, {"f": "Mellan vilka sorters grundämnen bildas oftast kovalenta bindningar?", "svar": "Mellan icke-metaller."}, {"f": "Hur många väteatomer och syreatomer finns i en vattenmolekyl, H₂O?", "svar": "Två väteatomer och en syreatom."}, {"f": "Vad betyder CO₂ och vad kallas ämnet?", "svar": "En kolatom och två syreatomer. Ämnet är koldioxid."}, {"f": "Hur många bindningar vill kol ha i den förenklade modellen, och varför?", "svar": "Fyra, eftersom kol har 4 valenselektroner och behöver 4 till för att få fullt yttersta skal."}]}], "begrepp": [{"term": "Kemisk bindning", "forklaring": "Det som håller ihop atomer."}, {"term": "Kemisk förening", "forklaring": "Ämne där atomer av olika grundämnen är bundna till varandra."}, {"term": "Kemisk reaktion", "forklaring": "Förändring där nya ämnen bildas."}, {"term": "Kovalent bindning", "forklaring": "Bindning där atomer delar elektronpar."}, {"term": "Molekyl", "forklaring": "Grupp av atomer som hålls ihop av kovalenta bindningar."}, {"term": "Molekylformel", "forklaring": "Visar vilka atomer och hur många som finns i molekylen."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Vad händer när atomer möts? Molekyler och kovalent bindning", "text": ["<p>Hur vet man att natriumklorid är NaCl men magnesiumklorid är MgCl₂? Svaret är att en jonförening alltid är neutral som helhet.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/f_formler.png\" alt=\"Bild F4.1 Formeln för en jonförening följer av jonernas laddning: den sammanlagda laddningen ska bli noll (schematiskt).\"><figcaption><strong>Bild F4.1</strong> Formeln för en jonförening följer av jonernas laddning: den sammanlagda laddningen ska bli noll (schematiskt).</figcaption></figure>", "<p>Ämnen i grupp 1 har en valenselektron och bildar joner med laddningen +1, ämnen i grupp 2 har två och bildar joner med laddningen +2. Syre (grupp 16) tar upp två elektroner och blir O²⁻, och klor (grupp 17) tar upp en och blir Cl⁻. Jonformeln hittar du genom att få laddningarna att ta ut varandra. Natrium (+1) och klor (−1) går ihop 1:1, så NaCl. Magnesium (+2) behöver två kloridjoner, så MgCl₂. Två natriumjoner behövs för en oxidjon, så Na₂O.</p>", "<p>Namnet bygger på jonerna: metallens namn först och icke-metallen med ändelsen <em>-id</em>: natriumklorid, magnesiumoxid. För molekylföreningar anger man ofta antalet atomer med förled som di-: koldioxid (CO₂) men kolmonoxid (CO). Många vardagsämnen har dock egna namn, som vatten och metan.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Aluminium (grupp 13) bildar Al³⁺ och syre bildar O²⁻. Hur många av varje jon behövs för att laddningen ska bli noll? Skriv formeln.</div>"]}, {"ikon": "📖", "titel": "Hur användbar är regeln?", "text": ["<p>Regeln med gruppnummer fungerar bra för de lätta grundämnena i grupp 1, 2 och 13 samt 16 och 17. Många ämnen längre ned i periodiska systemet, till exempel järn, kan bilda joner med olika laddning. Då måste laddningen anges. Det är ett exempel på en förenklad modell som är användbar men inte gäller överallt.</p>"]}], "begrepp": [{"term": "Jonformel", "forklaring": "Formel som visar förhållandet mellan jonerna."}, {"term": "Laddningsbalans", "forklaring": "Positiv och negativ laddning tar ut varandra."}, {"term": "Ändelsen -id", "forklaring": "Visar att icke-metallen är en anjon, till exempel klorid."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-4-1-2"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Joner och jonföreningar", "text": ["<p>En <strong>jon</strong> är en laddad atom. Den har avgett eller tagit upp elektroner.</p>", "<p>En positiv jon kallas <strong>katjon</strong>. En negativ jon kallas <strong>anjon</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_jon.png\" alt=\"\"></figure>", "<p>Natrium avger 1 elektron och blir Na⁺. Klor tar upp 1 elektron och blir Cl⁻.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th></th><th>Protoner</th><th>Elektroner</th><th>Laddning</th></tr><tr><td>Na</td><td>11</td><td>11</td><td>0</td></tr><tr><td>Na⁺</td><td>11</td><td>10</td><td>+1</td></tr><tr><td>Cl</td><td>17</td><td>17</td><td>0</td></tr><tr><td>Cl⁻</td><td>17</td><td>18</td><td>−1</td></tr></table></div>", "<p>Na⁺ och Cl⁻ drar till varandra. Det är <strong>jonbindning</strong>. Då bildas ett salt, till exempel bordssalt NaCl. Jonerna sitter i ett <strong>kristallgitter</strong>.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Jon = laddad atom. Katjon är positiv, anjon är negativ. Jonbindning: + och − drar till varandra.</div>"]}, {"ikon": "✏️", "titel": "Öva: Joner och jonföreningar", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad är en jon?", "val": ["En laddad atom", "En atom utan kärna", "En molekyl"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Na⁺ är en katjon.", "Cl⁻ är en positiv jon.", "Bordssalt är en jonförening."], "ratt": [true, false, true]}, {"typ": "streck", "fraga": "Dra streck till rätt namn.", "vanster": ["Katjon", "Anjon", "Jonbindning"], "hoger": ["+ och − drar till varandra", "negativ jon", "positiv jon"], "ratt": ["positiv jon", "negativ jon", "+ och − drar till varandra"]}, {"typ": "skriv", "fraga": "Hur blir en natriumatom en natriumjon?", "borja": "Den", "forslag": "Den avger en elektron och får laddningen +1."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Joner och jonföreningar", "text": ["<p>Atomer kan också få fullt yttersta skal genom att elektroner <em>flyttar</em>. En atom som avger eller tar upp elektroner blir en <strong>jon</strong>, alltså en laddad atom. Antalet protoner ändras inte, bara antalet elektroner. Laddningen är antalet protoner minus antalet elektroner.</p>", "<p>Natrium har elektronerna 2, 8, 1. Om natriumatomen avger sin enda valenselektron får den 2, 8, precis som ädelgasen neon. Den har 11 protoner men bara 10 elektroner och blir en natriumjon, Na⁺, med laddningen +1. Klor har 2, 8, 7. Tar kloratomen upp en elektron får den 2, 8, 8 och laddningen −1: en kloridjon, Cl⁻.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_jon.png\" alt=\"Bild 4.3 Natrium avger en elektron och blir Na⁺. Klor tar upp en elektron och blir Cl⁻. Elektronen som flyttar är orange (schematiskt).\"><figcaption><strong>Bild 4.3</strong> Natrium avger en elektron och blir Na⁺. Klor tar upp en elektron och blir Cl⁻. Elektronen som flyttar är orange (schematiskt).</figcaption></figure>"]}, {"ikon": "📖", "titel": "Jonbindning och salter", "text": ["<p>Metaller avger elektroner lätt och bildar katjoner. Icke-metaller tar upp elektroner och bildar anjoner. Kraften som drar positiva och negativa joner mot varandra kallas <strong>jonbindning</strong>. Ämnen som bildas av en metall och en icke-metall är <strong>jonföreningar</strong>, ofta kallade <strong>salter</strong>.</p>", "<p>Jonerna bildar inte enskilda par utan ett stort, regelbundet mönster, ett <strong>kristallgitter</strong>. I natriumklorid, vanligt bordssalt, omges varje natriumjon av kloridjoner och tvärtom. Formeln NaCl visar förhållandet: en natriumjon för varje kloridjon.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_kristall.png\" alt=\"Bild 4.4 Natriumklorid (schematiskt): positiva natriumjoner och negativa kloridjoner i ett regelbundet gitter. Bilden visar ett plan.\"><figcaption><strong>Bild 4.4</strong> Natriumklorid (schematiskt): positiva natriumjoner och negativa kloridjoner i ett regelbundet gitter. Bilden visar ett plan.</figcaption></figure>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför är bordssalt, NaCl, elektriskt neutralt även om det består av laddade joner? Och varför kan inte två Na⁺ bilda en bindning med varandra?</div>"], "fragor": [{"f": "Vad är en jon?", "svar": "En atom (eller grupp av atomer) som har fått en laddning genom att avge eller ta upp elektroner."}, {"f": "Vad är skillnaden mellan katjon och anjon?", "svar": "Katjon är en positiv jon och anjon är en negativ jon."}, {"f": "Hur bildas en natriumjon, Na⁺, och vilken elektronfördelning får den?", "svar": "Natrium (2, 8, 1) avger en elektron och får 2, 8. Det är 11 protoner och 10 elektroner, så laddningen är +1."}, {"f": "Hur bildas en kloridjon, Cl⁻?", "svar": "Klor (2, 8, 7) tar upp en elektron och får 2, 8, 8. Det är 17 protoner och 18 elektroner, så laddningen är −1."}, {"f": "Vad är jonbindning?", "svar": "Attraktionen mellan positiva och negativa joner."}, {"f": "Hur är en saltkristall uppbyggd?", "svar": "Av positiva och negativa joner som sitter i ett regelbundet jonkristallgitter, där varje jon omges av motsatt laddade joner."}]}], "begrepp": [{"term": "Anjon", "forklaring": "Negativ jon, till exempel Cl⁻."}, {"term": "Jon", "forklaring": "Laddad atom (eller grupp av atomer)."}, {"term": "Jonbindning", "forklaring": "Attraktion mellan positiva och negativa joner."}, {"term": "Katjon", "forklaring": "Positiv jon, till exempel Na⁺."}, {"term": "Kristallgitter", "forklaring": "Regelbundet mönster av joner."}, {"term": "Salt", "forklaring": "Jonförening av en metall och en icke-metall."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Joner och jonföreningar", "text": ["<p>I grundtexten mötte du kovalent bindning och jonbindning. Det finns en tredje huvudsort, <strong>metallbindning</strong>, som förklarar varför metaller leder ström och går att forma.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/f_metall.png\" alt=\"Bild F4.2 Metallbindning (schematiskt): positiva metalljoner hålls ihop av ett hav av fria elektroner som rör sig mellan dem.\"><figcaption><strong>Bild F4.2</strong> Metallbindning (schematiskt): positiva metalljoner hålls ihop av ett hav av fria elektroner som rör sig mellan dem.</figcaption></figure>", "<p>I en metall avger atomerna sina yttre elektroner, som inte sitter fast vid någon särskild atom. De positiva metalljonerna hålls ihop av attraktionen till elektronerna som rör sig fritt mellan dem. Eftersom elektronerna är fria leder metaller el och värme. Och eftersom jonerna kan glida förbi varandra utan att bindningen bryts går metaller att böja och hamra.</p>", "<p>Jonföreningar är i stället hårda men spröda. Om ett lager joner förskjuts ett steg hamnar joner med lika laddning intill varandra och stöter bort varandra, så kristallen spricker.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th></th><th>Kovalent</th><th>Jon</th><th>Metall</th></tr><tr><td>Partiklar</td><td>Atomer som delar</td><td>Joner</td><td>Joner + fria e⁻</td></tr><tr><td>Leder fast</td><td>Nej</td><td>Nej</td><td>Ja</td></tr><tr><td>Formbar</td><td>–</td><td>Spröd</td><td>Ja</td></tr></table></div>"]}, {"ikon": "📖", "titel": "Gränserna är glidande", "text": ["<p>Bindningstyperna är modeller. Många riktiga bindningar ligger mellan ytterligheterna: elektronerna delas ibland ojämnt (polär bindning), och i vissa jonföreningar är bindningen delvis kovalent. Modellerna är användbara för att förutsäga egenskaper, men man måste känna till deras gränser.</p>"]}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-4-1-3"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Egenskaper hos föreningar", "text": ["<p>Hur ett ämne är uppbyggt avgör hur det beter sig.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th></th><th>Molekylförening</th><th>Jonförening</th></tr><tr><td>Smältpunkt</td><td>oftast låg</td><td>hög (salt ca 800 °C)</td></tr><tr><td>Fast ämne leder ström?</td><td>nej</td><td>nej</td></tr><tr><td>Löst eller smält leder ström?</td><td>nej</td><td>ja</td></tr></table></div>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_ledning.png\" alt=\"\"></figure>", "<p>Salt smälter vid ungefär 800 °C. Vatten fryser vid 0 °C. Jonerna i salt hålls ihop hårt.</p>", "<p>Fast salt leder inte ström. Jonerna sitter fast. I saltvatten kan jonerna röra sig, så saltvatten leder ström. Ett sådant ämne kallas <strong>elektrolyt</strong>.</p>", "<p>Sockervatten leder inte ström. Det finns inga joner.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Salt har hög smältpunkt. Saltvatten leder ström, fast salt och sockervatten gör det inte.</div>"]}, {"ikon": "✏️", "titel": "Öva: Egenskaper hos föreningar", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vilken vätska leder ström?", "val": ["Saltvatten", "Sockervatten", "Destillerat vatten"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Fast salt leder ström.", "Salt har hög smältpunkt.", "Sockervatten innehåller joner."], "ratt": [false, true, false]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["elektrolyt", "fast", "joner"], "meningar": ["Saltvatten leder ström för att det finns §.", "I § salt sitter jonerna fast.", "Ett ämne som leder ström när det är löst är en §."], "ratt": ["joner", "fast", "elektrolyt"]}, {"typ": "skriv", "fraga": "Varför leder inte sockervatten ström?", "borja": "Det beror på att", "forslag": "Sockervatten har inga joner som kan bära strömmen."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Egenskaper hos föreningar", "text": ["<p>Hur ett ämne är uppbyggt avgör hur det beter sig. Det gäller smältpunkt, ledningsförmåga och löslighet. Här jämför vi molekylföreningar, jonföreningar och metaller.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th></th><th>Molekylföreningar (t.ex. H₂O, CO₂, CH₄)</th><th>Jonföreningar (t.ex. NaCl)</th><th>Metaller</th></tr><tr><td><strong>Byggs upp av</strong></td><td>Molekyler</td><td>Joner i ett gitter</td><td>Metallatomer</td></tr><tr><td><strong>Smält- och kokpunkt</strong></td><td>Oftast låga. Svaga krafter mellan molekylerna.</td><td>Höga. Bordssalt smälter vid ungefär 800 °C.</td><td>Oftast höga</td></tr><tr><td><strong>Leder ström</strong></td><td>Nej</td><td>Fast: nej. Löst eller smält: ja.</td><td>Ja</td></tr><tr><td><strong>Löser sig i vatten</strong></td><td>Varierar: socker löser sig</td><td>Ofta ja</td><td>Nej</td></tr></table></div>"]}, {"ikon": "📖", "titel": "Smältpunkt", "text": ["<p>Vatten fryser vid 0 °C, men bordssalt smälter först vid ungefär 800 °C. Skillnaden beror på bindningarna. I en jonförening hålls jonerna fast av starka krafter i gittret, och det krävs mycket energi för att få dem att röra sig. Mellan molekylerna i en molekylförening är krafterna svaga, så det går åt lite energi. Därför är jonföreningar vid rumstemperatur oftast fasta, medan molekylföreningar ofta är gaser eller vätskor.</p>"]}, {"ikon": "📖", "titel": "Ledningsförmåga", "text": ["<p>För att leda elektrisk ström behövs <em>rörliga laddade partiklar</em>. I fast salt sitter jonerna fast i gittret, så fast salt leder inte. Löser man saltet i vatten drar vattenmolekylerna loss jonerna från gittret, och då kan de röra sig och bära strömmen. Detsamma gäller om saltet smälts. Ett ämne som leder ström när det är löst eller smält kallas en <strong>elektrolyt</strong>.</p>", "<p>Sockerlösning leder inte ström, eftersom socker består av molekyler utan laddning. Rent vatten leder dåligt, men kranvatten leder lite eftersom det innehåller små mängder lösta salter. Metaller leder ström som fast ämne, vilket du får veta mer om i fördjupningen.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_ledning.png\" alt=\"Bild 4.5 Lampan lyser bara om det finns rörliga laddade partiklar: fast salt leder inte, saltlösning leder och sockerlösning leder inte (schematiskt).\"><figcaption><strong>Bild 4.5</strong> Lampan lyser bara om det finns rörliga laddade partiklar: fast salt leder inte, saltlösning leder och sockerlösning leder inte (schematiskt).</figcaption></figure>"], "fragor": [{"f": "Varför har jonföreningar höga smältpunkter?", "svar": "Jonerna hålls ihop av starka krafter i gittret, så det krävs mycket energi för att få isär dem. Bordssalt smälter vid ungefär 800 °C."}, {"f": "Varför har molekylföreningar ofta låga smältpunkter?", "svar": "Krafterna mellan molekylerna är svaga, så det går åt lite energi för att få dem att röra sig fritt."}, {"f": "Leder fast salt elektrisk ström? Motivera.", "svar": "Nej. Jonerna sitter fast i gittret och kan inte röra sig."}, {"f": "När leder en jonförening ström?", "svar": "När den är löst i vatten eller smält, eftersom jonerna då kan röra sig fritt."}, {"f": "Vad är en elektrolyt?", "svar": "Ett ämne som leder ström när det är löst eller smält, eftersom det innehåller rörliga joner."}, {"f": "Varför leder sockerlösning inte ström?", "svar": "Socker består av molekyler utan laddning. Det finns inga fria joner som kan bära strömmen."}]}], "begrepp": [{"term": "Elektrolyt", "forklaring": "Ämne som leder ström när det är löst eller smält."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Egenskaper hos föreningar", "text": ["<p>Delar atomerna elektronerna lika? Svaret beror på hur starkt de drar i elektronerna.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/f_polar.png\" alt=\"Bild F4.3 Vatten är polärt (bindningarna dras mot syre, de tar inte ut varandra) och koldioxid är opolärt (bindningarna tar ut varandra).\"><figcaption><strong>Bild F4.3</strong> Vatten är polärt (bindningarna dras mot syre, de tar inte ut varandra) och koldioxid är opolärt (bindningarna tar ut varandra).</figcaption></figure>", "<p><strong>Elektronegativitet</strong> är en atoms förmåga att dra till sig elektronerna i en bindning. Linus Pauling gjorde den första skalan. Syre har värdet 3,5, klor 3,0, kol 2,5 och väte 2,1. Skillnaden mellan atomernas värden säger vilken sorts bindning det är: under ungefär 0,5 är bindningen opolär, mellan ungefär 0,5 och 2,0 polär kovalent, och över ungefär 2,0 liknar den en jonbindning. Gränserna är något godtyckliga.</p>", "<p>I en polär bindning delas elektronerna ojämnt. Den mer elektronegativa atomen får en liten negativ laddning (δ−) och den andra en liten positiv (δ+). O–H-bindningen har skillnaden 1,4 och är polär, C–H-bindningen har 0,4 och är opolär.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Beräkna skillnaden i elektronegativitet för H–Cl (H 2,1, Cl 3,0). Är bindningen polär eller opolär? Vilken atom får δ−?</div>"]}, {"ikon": "📖", "titel": "Polära molekyler", "text": ["<p>Om en molekyl har polära bindningar som inte tar ut varandra är hela molekylen polär. Vatten är vinklat, så bindningarna tar inte ut varandra och molekylen får en positiv och en negativ sida. Koldioxid är rak, och de två bindningarna drar åt motsatta håll, så molekylen som helhet är opolär. Polära molekyler har oftast högre smält- och kokpunkter och löser sig bättre i vatten än opolära.</p>"]}], "begrepp": [{"term": "Elektronegativitet", "forklaring": "Hur starkt en atom drar i elektronerna i en bindning."}, {"term": "Opolär bindning", "forklaring": "Elektronerna delas ungefär lika."}, {"term": "Polär bindning", "forklaring": "Elektronerna delas ojämnt."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-4-1-l"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧪", "titel": "Labb 4.1 Leder lösningar elektrisk ström?", "text": ["<p><strong>Fråga:</strong> Vilka vätskor leder elektrisk ström?</p>", "<p>Du behöver: batteri (4,5 V), lampa, sladdar, två elektroder, destillerat vatten, saltvatten, sockervatten, kranvatten och skyddsglasögon.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_labb1.png\" alt=\"\"></figure>", "<ol><li>Koppla kretsen. Testa att lampan lyser när elektroderna rör varandra.</li><li>Sänk elektroderna i en vätska. Rör dem inte ihop.</li><li>Skriv om lampan lyser.</li><li>Skölj elektroderna mellan vätskorna.</li></ol>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Vätska</th><th>Lampan lyser?</th></tr><tr><td>Destillerat vatten</td><td></td></tr><tr><td>Saltvatten</td><td></td></tr><tr><td>Sockervatten</td><td></td></tr><tr><td>Kranvatten</td><td></td></tr></table></div>", "<p><strong>Säkerhet:</strong> Använd bara batteriet, aldrig vägguttag. Ha skyddsglasögon. Smaka inte. Tvätta händerna.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Lösningar med joner leder ström. Lösningar utan joner gör det inte.</div>"]}, {"ikon": "✏️", "titel": "Öva: Labb 4.1 Leder lösningar elektrisk ström?", "text": [], "ovningar": [{"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["joner", "lyste", "saltvatten"], "meningar": ["Lampan § i en av vätskorna.", "Det var §.", "Det finns § i den vätskan."], "ratt": ["lyste", "saltvatten", "joner"]}, {"typ": "skriv", "fraga": "Vilka vätskor ledde inte ström?", "borja": "De som inte ledde var", "forslag": "Sockervatten och destillerat vatten."}, {"typ": "skriv", "fraga": "Varför leder saltvatten ström?", "borja": "Det beror på att", "forslag": "Det finns joner som kan röra sig i saltvattnet."}]}]}, "vanlig": {"sektioner": [{"ikon": "🧪", "titel": "Labb 4.1 Leder lösningar elektrisk ström?", "text": ["<p>Du har lärt dig att det behövs rörliga joner för att en lösning ska leda ström. I det här försöket testar du det genom att jämföra fyra vätskor med en enkel krets.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_labb1.png\" alt=\"Bild 4.6 Kopplingsschema: batteri, lampa och två elektroder som sänks ned i lösningen.\"><figcaption><strong>Bild 4.6</strong> Kopplingsschema: batteri, lampa och två elektroder som sänks ned i lösningen.</figcaption></figure>", "<p><strong>Frågeställning:</strong> Vilka av vätskorna destillerat vatten, saltvatten, sockervatten och kranvatten leder elektrisk ström?</p>", "<p><strong>Hypotes:</strong> Skriv vad du tror för varje vätska och förklara med joner.</p>", "<p><strong>Material:</strong> batteri 4,5 V, liten glödlampa, sladdar, två elektroder (grafitstavar eller blyertsstift), fyra bägare med destillerat vatten, saltvatten, sockervatten och kranvatten, destillerat vatten och hushållspapper för sköljning, skyddsglasögon.</p>"]}, {"ikon": "📖", "titel": "Gör så här", "text": ["<ol><li>Koppla kretsen enligt bilden. Testa att den fungerar genom att hålla elektroderna mot varandra: lampan ska lysa.</li><li>Sänk ned elektroderna i den första vätskan så att de inte rör varandra. Notera om lampan lyser starkt, svagt eller inte alls.</li><li>Skölj elektroderna i destillerat vatten och torka dem mellan varje vätska.</li><li>Testa alla fyra vätskor och fyll i tabellen.</li><li>Förklara resultaten med joner.</li></ol>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Bra att veta</span>En svag ström syns kanske inte som ljus i lampan. Jämför därför alltid med destillerat vatten.</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Vätska</th><th>Lampan lyser?</th><th>Leder strömmen?</th></tr><tr><td>Destillerat vatten</td><td></td><td></td></tr><tr><td>Saltvatten</td><td></td><td></td></tr><tr><td>Sockervatten</td><td></td><td></td></tr><tr><td>Kranvatten</td><td></td><td></td></tr></table></div>", "<p class=\"not\">Säkerhet: Använd bara batteriet (högst 4,5 V). Använd aldrig vägguttag. Ha skyddsglasögon. Håll försöket kort, för vid elektroderna kan små mängder gas bildas. Smaka inte på något. Torka upp spill och tvätta händerna.</p>"]}, {"ikon": "❓", "titel": "Frågor", "text": ["<ol><li>Vilka vätskor ledde ström, och vad innehåller de som de andra saknar?</li><li>Varför ledde sockervattnet inte, fast socker löser sig i vatten?</li><li>Hur säker är din slutsats om kranvattnet? Vad kunde du göra för att bli säkrare?</li></ol>"]}], "begrepp": [{"term": "Elektrod", "forklaring": "Ledare som för in strömmen i vätskan."}, {"term": "Elektrolyt", "forklaring": "Ämne som leder ström när det är löst eller smält."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-4-2-1"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Vad är en kemisk reaktion?", "text": ["<p>I en <strong>kemisk reaktion</strong> bildas nya ämnen. Ämnena du börjar med är <strong>utgångsämnen</strong>. Ämnena som bildas är <strong>produkter</strong>.</p>", "<p>Exempel: <strong>metan + syre → koldioxid + vatten</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_reaktion.png\" alt=\"\"></figure>", "<p>Tecken på reaktion: gas bildas, temperaturen ändras, färgen ändras, ett fast ämne bildas, ljus eller lukt.</p>", "<p>Men bubblor räcker inte. Kokande vatten bubblar också, och det är fortfarande vatten.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Förändring</th><th>Kemisk eller fysikalisk?</th></tr><tr><td>Isbit smälter</td><td>fysikalisk</td></tr><tr><td>Socker löses i vatten</td><td>fysikalisk</td></tr><tr><td>Papper brinner</td><td>kemisk</td></tr><tr><td>Spik rostar</td><td>kemisk</td></tr></table></div>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Kemisk reaktion: nya ämnen bildas. Fysikalisk förändring: samma ämne byter tillstånd eller form.</div>"]}, {"ikon": "✏️", "titel": "Öva: Vad är en kemisk reaktion?", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad kallas ämnena som bildas?", "val": ["Produkter", "Utgångsämnen", "Elektroder"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Ett papper som brinner är en kemisk reaktion.", "När is smälter bildas ett nytt ämne.", "Gasbildning kan vara ett tecken på reaktion."], "ratt": [true, false, true]}, {"typ": "streck", "fraga": "Dra streck till rätt typ.", "vanster": ["Isbit smälter", "Spik rostar", "Socker löses"], "hoger": ["fysikalisk", "fysikalisk", "kemisk"], "ratt": ["fysikalisk", "kemisk", "fysikalisk"]}, {"typ": "skriv", "fraga": "Nämn två tecken på en kemisk reaktion.", "borja": "Två tecken är", "forslag": "Till exempel gasbildning och temperaturförändring."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Vad är en kemisk reaktion?", "text": ["<p>I en <strong>kemisk reaktion</strong> omvandlas ett eller flera ämnen till nya ämnen med andra egenskaper. Ämnena du börjar med kallas <strong>utgångsämnen</strong> (reaktanter), och ämnena som bildas kallas <strong>produkter</strong>. Man skriver reaktionen med en pil: utgångsämnen → produkter.</p>", "<p>Exempel: när metan i naturgas brinner reagerar den med syre och bildar koldioxid och vatten. Reaktionen kan skrivas <strong>metan + syre → koldioxid + vatten</strong>. När järn rostar reagerar det med syre (och vatten) och bildar järnoxid: <strong>järn + syre → järnoxid</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_reaktion.png\" alt=\"Bild 4.7 Vätgas och syrgas reagerar och bildar vatten (schematiskt): atomerna byter partner men inga atomer försvinner.\"><figcaption><strong>Bild 4.7</strong> Vätgas och syrgas reagerar och bildar vatten (schematiskt): atomerna byter partner men inga atomer försvinner.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Tecken på kemisk reaktion", "text": ["<p>Det finns några vanliga tecken på att en kemisk reaktion har skett:</p>", "<ul><li><strong>Gas bildas:</strong> det bubblar eller fräser, till exempel när bikarbonat blandas med ättika.</li><li><strong>Temperaturen ändras:</strong> det blir varmare eller kallare utan att du värmer eller kyler.</li><li><strong>Färgen ändras</strong> eller ett <strong>fast ämne bildas</strong> i en lösning.</li><li><strong>Ljus eller lukt</strong> uppstår, till exempel vid förbränning.</li></ul>", "<p>Tecknen visar att något <em>kan</em> ha hänt, men de bevisar inte alltid en reaktion. Kokande vatten bubblar också, men det är fortfarande vatten.</p>"]}, {"ikon": "📖", "titel": "Kemisk eller fysikalisk förändring?", "text": ["<p>I en <strong>fysikalisk förändring</strong> är det samma ämne som byter tillstånd eller form. Atomerna sitter ihop på samma sätt som förut. I en kemisk förändring bryts bindningar och nya ämnen bildas.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Förändring</th><th>Typ</th><th>Varför</th></tr><tr><td>En isbit smälter</td><td>Fysikalisk</td><td>Fortfarande vatten, bara annat tillstånd</td></tr><tr><td>Socker löses i vatten</td><td>Fysikalisk</td><td>Sockret finns kvar och kan fås tillbaka när vattnet dunstar</td></tr><tr><td>Ett papper brinner</td><td>Kemisk</td><td>Nya ämnen bildas, bland annat koldioxid och vatten</td></tr><tr><td>En järnspik rostar</td><td>Kemisk</td><td>Järnoxid bildas, ett nytt ämne</td></tr></table></div>"], "fragor": [{"f": "Vad kallas ämnena före och efter en kemisk reaktion?", "svar": "Utgångsämnen (reaktanter) före och produkter efter."}, {"f": "Nämn tre tecken på att en kemisk reaktion har skett.", "svar": "Gasbildning (bubblor), färgförändring, temperaturförändring, att ett fast ämne bildas eller ljus och lukt."}, {"f": "Varför bevisar inte bubblor ensamma att en kemisk reaktion skett?", "svar": "Kokande vatten bildar också bubblor, men det är fortfarande vatten (en fysikalisk förändring)."}, {"f": "Vad är skillnaden mellan kemisk och fysikalisk förändring?", "svar": "I en kemisk förändring bildas nya ämnen. I en fysikalisk förändring är det samma ämne som byter tillstånd eller form."}, {"f": "Är det kemisk eller fysikalisk förändring när socker löses i vatten? Motivera.", "svar": "Fysikalisk. Sockret är kvar och går att få tillbaka genom att låta vattnet dunsta."}, {"f": "Skriv reaktionen när metan brinner med ord.", "svar": "metan + syre → koldioxid + vatten"}]}], "begrepp": [{"term": "Ny substans", "forklaring": "Ämne med egenskaper som skiljer sig från utgångsämnena."}, {"term": "Produkt", "forklaring": "Ämne som bildas."}, {"term": "Utgångsämne", "forklaring": "Ämne som reagerar. Kallas också reaktant."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Vad är en kemisk reaktion?", "text": ["<p>Förbränning är en av de vanligaste kemiska reaktionerna i vardagen: ljus, brasor, gasspisar och motorer. Här tittar vi på reaktionsformlerna och på hur man släcker bränder.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/f_brand.png\" alt=\"Bild F4.4 Brandtriangeln: en brand behöver bränsle, syre och värme. Tar man bort en av dem slocknar branden.\"><figcaption><strong>Bild F4.4</strong> Brandtriangeln: en brand behöver bränsle, syre och värme. Tar man bort en av dem slocknar branden.</figcaption></figure>", "<p>Vid fullständig förbränning av ett kolväte bildas koldioxid och vatten och energi avges. Metan: CH₄ + 2 O₂ → CO₂ + 2 H₂O. Etanol: C₂H₅OH + 3 O₂ → 2 CO₂ + 3 H₂O. Kontrollera själv: på båda sidor finns 2 C, 6 H och 7 O i etanolreaktionen. Vid brist på syre blir förbränningen ofullständig och det kan bildas kolmonoxid och sot. Kolmonoxid är giftig och luktfri, därför är det viktigt med god ventilation vid eldning.</p>", "<p>Man släcker en brand genom att ta bort något av det som behövs. Vatten kyler, och tar alltså bort värme. En brandfilt eller ett lock täcker över och tar bort syre. Vid en fettbrand ska man aldrig använda vatten, eftersom det kan få det heta fettet att stänka kraftigt. Man kan också ta bort bränsle, till exempel genom att stänga av gasen.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför slocknar ett stearinljus under ett upp-och-nedvänt glas? Använd brandtriangeln och förklara varför det slocknar efter en stund.</div>"]}, {"ikon": "📖", "titel": "Hur användbar är brandtriangeln?", "text": ["<p>Brandtriangeln är en förenklad modell som ger en bra tumregel för att släcka bränder. Verkligheten är mer komplicerad: olika material och bränder kräver olika släckmedel, och därför ska man följa lokala råd och släckutrustningens märkning.</p>"]}], "begrepp": [{"term": "Brandtriangeln", "forklaring": "Bränsle, syre och värme."}, {"term": "Fullständig förbränning", "forklaring": "Ger koldioxid och vatten."}, {"term": "Ofullständig förbränning", "forklaring": "Ger bland annat kolmonoxid och sot."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-4-2-2"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Reaktionsformler och oförstörbarhet", "text": ["<p>En <strong>reaktionsformel</strong> visar reaktionen med formler. Atomerna försvinner inte. Därför måste det vara lika många atomer av varje sort på båda sidor.</p>", "<p>Man <strong>balanserar</strong> genom att sätta tal framför formlerna. Ändra aldrig talen inne i formlerna.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_balans.png\" alt=\"\"></figure>", "<p><strong>2 H₂ + O₂ → 2 H₂O</strong></p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Atom</th><th>Före (2 H₂ + O₂)</th><th>Efter (2 H₂O)</th></tr><tr><td>H</td><td>4</td><td>4</td></tr><tr><td>O</td><td>2</td><td>2</td></tr></table></div>", "<p><strong>Massan bevaras</strong>: massan är lika stor före och efter i en sluten behållare. Lavoisier visade det. I en öppen flaska kan massan minska om en gas lämnar.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Balansera: lika många atomer av varje sort på båda sidor. Massan bevaras.</div>"]}, {"ikon": "✏️", "titel": "Öva: Reaktionsformler och oförstörbarhet", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad får man aldrig ändra när man balanserar?", "val": ["Talen inne i formlerna", "Talen framför formlerna", "Pilen"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Atomer försvinner i en reaktion.", "2 H₂O har 4 väteatomer.", "Massan bevaras i en sluten behållare."], "ratt": [false, true, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["balansera", "bildas", "lika"], "meningar": ["Man måste § formeln.", "Det ska vara § många atomer på båda sidor.", "När en gas § i en öppen flaska kan vågen visa mindre."], "ratt": ["balansera", "lika", "bildas"]}, {"typ": "skriv", "fraga": "Räkna: hur många H-atomer finns i 2 H₂O?", "borja": "Det finns", "forslag": "Det finns 4 väteatomer."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Reaktionsformler och oförstörbarhet", "text": ["<p>En <strong>reaktionsformel</strong> visar en reaktion med kemiska formler i stället för ord. Vätgas och syrgas som bildar vatten blir H₂ + O₂ → H₂O. Räknar vi atomerna har vi två väteatomer och två syreatomer till vänster men bara en syreatom till höger. En syreatom har försvunnit, men det kan inte ske. Atomer skapas eller förstörs inte i kemiska reaktioner, de byter bara partner.</p>", "<p>Därför måste formeln <strong>balanseras</strong>, så att det finns lika många atomer av varje sort på båda sidor. Det gör man genom att sätta <strong>koefficienter</strong>, alltså tal framför formlerna.</p>"]}, {"ikon": "📖", "titel": "Så balanserar du", "text": ["<ol><li>Skriv formeln med rätt formler för alla ämnen: H₂ + O₂ → H₂O.</li><li>Räkna atomerna på båda sidor. Här finns 2 O till vänster men 1 O till höger.</li><li>Sätt koefficienter framför formlerna tills det är lika. Skriv 2 H₂O: då finns 2 O till höger, men 4 H. Sätt då 2 H₂ till vänster.</li><li>Kontrollera: 2 H₂ + O₂ → 2 H₂O har 4 H och 2 O på båda sidor.</li></ol>", "<p class=\"not\">Ändra aldrig talen inne i en formel. H₂O är vatten, men H₂O₂ är ett annat ämne.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_balans.png\" alt=\"Bild 4.8 Metan brinner (schematiskt): CH₄ + 2 O₂ → CO₂ + 2 H₂O. Det finns 1 C, 4 H och 4 O på båda sidor.\"><figcaption><strong>Bild 4.8</strong> Metan brinner (schematiskt): CH₄ + 2 O₂ → CO₂ + 2 H₂O. Det finns 1 C, 4 H och 4 O på båda sidor.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Massans bevarande", "text": ["<p>Eftersom inga atomer försvinner är massan lika stor före och efter en reaktion i ett slutet system. Det visade Antoine Lavoisier på 1780-talet med noggranna vägningar. Om 10 g av ett ämne reagerar helt med 8 g av ett annat och bara en produkt bildas, väger produkten 18 g (påhittade siffror). Om en gas bildas i en öppen behållare kan vågen ändå visa mindre massa, för gasen har lämnat behållaren och tagit sin massa med sig.</p>", "<p>Tre vanliga reaktioner är <strong>förbränning</strong> (bränsle + syre → koldioxid + vatten, energi avges), <strong>rostning</strong> eller oxidation av järn (järn + syre + vatten → järnoxid) och <strong>syra mot metall</strong> (metall + syra → salt + vätgas, gas bubblar upp).</p>"], "fragor": [{"f": "Varför måste man balansera en reaktionsformel?", "svar": "Atomerna varken skapas eller förstörs, så det måste finnas lika många av varje sort på båda sidor."}, {"f": "Vad är en koefficient och var skriver man den?", "svar": "Talet framför en formel. Det anger hur många molekyler (eller formelenheter) som reagerar eller bildas."}, {"f": "Vad får man aldrig göra när man balanserar?", "svar": "Ändra talen inne i formlerna, eftersom det skulle byta ut ämnet."}, {"f": "Balansera: H₂ + O₂ → H₂O.", "svar": "2 H₂ + O₂ → 2 H₂O"}, {"f": "Vad menas med massans bevarande, och vem visade det med noggranna vägningar?", "svar": "Att massan är lika stor före och efter en reaktion i ett slutet system. Lavoisier visade det på 1780-talet."}, {"f": "Varför kan massan minska på en våg när en gas bildas i en öppen flaska?", "svar": "Gasen lämnar flaskan och tar sin massa med sig. Atomerna har inte försvunnit."}]}], "begrepp": [{"term": "Balansera", "forklaring": "Se till att lika många atomer av varje sort finns på båda sidor."}, {"term": "Koefficient", "forklaring": "Talet framför en formel i en reaktionsformel."}, {"term": "Reaktionsformel", "forklaring": "Reaktionen skriven med kemiska formler."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Reaktionsformler och oförstörbarhet", "text": ["<p>Varje år rostar mycket järn och stål. Hur kan man skydda det?</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/f_rost.png\" alt=\"Bild F4.5 Rost och tre sätt att skydda järn: skikt av färg eller zink och en offeranod (schematiskt).\"><figcaption><strong>Bild F4.5</strong> Rost och tre sätt att skydda järn: skikt av färg eller zink och en offeranod (schematiskt).</figcaption></figure>", "<p>Rost bildas när järn reagerar med syre i närvaro av vatten: järn + syre + vatten → rost (järnoxid, förenklat 4 Fe + 3 O₂ → 2 Fe₂O₃). Både syre och vatten behövs, så nyckeln till att skydda järn är att hålla syre och vatten borta. Rosten flagnar, vilket gör att järnet under fortsätter rosta.</p>", "<p>Skydden bygger på olika principer. <strong>Färg och olja</strong> är en barriär men måste täcka hela ytan och underhållas. <strong>Galvanisering</strong> är ett skikt av zink: zinken är mer reaktiv än järn och rostar först, så den skyddar även om skiktet repas. En <strong>offeranod</strong> av magnesium eller zink som kopplas till järn används på fartyg och rörledningar, och metallen offrar sig. En <strong>legering</strong> som rostfritt stål innehåller krom, som bildar ett tunt oxidskikt som skyddar.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför är det olämpligt att skydda en stålbåt med en bit koppar i stället för zink? Ledtråd: vilken metall är mest reaktiv?</div>"]}, {"ikon": "📖", "titel": "Vilket skydd är bäst?", "text": ["<p>Det beror på situationen. Färg är billigt men kräver underhåll, zink skyddar även vid repor, offeranod passar för föremål som sitter i vatten eller jord, och rostfritt stål är dyrare men håller länge. Ett bra svar väger kostnad, hållbarhet och miljö.</p>"]}], "begrepp": [{"term": "Galvanisering", "forklaring": "Skikt av zink på järn."}, {"term": "Korrosion", "forklaring": "Att en metall bryts ned av reaktion med omgivningen."}, {"term": "Offeranod", "forklaring": "Mer reaktiv metall som rostar i stället för järnet."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-4-2-3"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Hastighet och energi", "text": ["<p><strong>Reaktionshastighet</strong> är hur fort en reaktion går. Partiklarna måste krocka för att reagera.</p>", "<p>Reaktionen går fortare vid högre temperatur, högre koncentration, större ytarea och med en <strong>katalysator</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_hastighet.png\" alt=\"\"></figure>", "<p>En <strong>exoterm</strong> reaktion avger energi. En <strong>endoterm</strong> reaktion tar upp energi.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_energi.png\" alt=\"\"></figure>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th></th><th>Exoterm</th><th>Endoterm</th></tr><tr><td>Energi</td><td>avges</td><td>tas upp</td></tr><tr><td>Omgivningen</td><td>blir varmare</td><td>blir kallare</td></tr><tr><td>Exempel</td><td>förbränning</td><td>ättika + bikarbonat</td></tr></table></div>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Fler och hårdare krockar ger snabbare reaktion. Exoterm: varmare. Endoterm: kallare.</div>"]}, {"ikon": "✏️", "titel": "Öva: Hastighet och energi", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad gör en katalysator?", "val": ["Reaktionen går fortare", "Reaktionen går långsammare", "Den förbrukas"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Hög temperatur ger snabbare reaktion.", "Exoterm betyder att energi tas upp.", "Förbränning avger energi."], "ratt": [true, false, true]}, {"typ": "streck", "fraga": "Dra streck till rätt ord.", "vanster": ["Exoterm", "Endoterm", "Katalysator"], "hoger": ["avger energi", "tar upp energi", "ökar hastigheten"], "ratt": ["avger energi", "tar upp energi", "ökar hastigheten"]}, {"typ": "skriv", "fraga": "Hur kan du få en reaktion att gå fortare?", "borja": "Man kan", "forslag": "Man kan höja temperaturen eller smula sönder ett fast ämne."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Hastighet och energi", "text": ["<p><strong>Reaktionshastigheten</strong> säger hur snabbt utgångsämnen förbrukas eller produkter bildas. För att en reaktion ska ske måste partiklarna krocka med varandra med tillräcklig energi och rätt riktning. Allt som ger fler eller hårdare krockar gör reaktionen snabbare:</p>", "<ul><li><strong>Högre temperatur:</strong> partiklarna rör sig snabbare och krockar oftare och hårdare.</li><li><strong>Högre koncentration:</strong> partiklarna sitter tätare, så de krockar oftare.</li><li><strong>Större ytarea:</strong> finfördelat fast ämne har fler partiklar att krocka med.</li><li><strong>Katalysator:</strong> får reaktionen att gå fortare utan att förbrukas (t.ex. enzymer i kroppen).</li></ul>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_hastighet.png\" alt=\"Bild 4.9 Fler och hårdare krockar ger snabbare reaktion (schematiskt).\"><figcaption><strong>Bild 4.9</strong> Fler och hårdare krockar ger snabbare reaktion (schematiskt).</figcaption></figure>"]}, {"ikon": "📖", "titel": "Energi i reaktioner", "text": ["<p>För att bryta bindningar behövs energi, och när nya bindningar bildas avges energi. Avges mer energi än som behövs är reaktionen <strong>exoterm</strong>: energi avges till omgivningen, som blir varmare. Förbränning är exotermt. Behövs mer energi än som avges är reaktionen <strong>endoterm</strong>: energi tas upp, och omgivningen blir kallare. När ättika och bikarbonat reagerar sjunker temperaturen, så det är en endoterm reaktion.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_energi.png\" alt=\"Bild 4.10 Energidiagram (schematiskt): vid en exoterm reaktion har produkterna mindre energi än utgångsämnena, vid en endoterm reaktion mer.\"><figcaption><strong>Bild 4.10</strong> Energidiagram (schematiskt): vid en exoterm reaktion har produkterna mindre energi än utgångsämnena, vid en endoterm reaktion mer.</figcaption></figure>"], "fragor": [{"f": "Vad är reaktionshastighet?", "svar": "Hur snabbt utgångsämnen förbrukas eller produkter bildas."}, {"f": "Nämn fyra saker som påverkar reaktionshastigheten.", "svar": "Temperatur, koncentration, ytarea (hur finfördelat ett fast ämne är) och katalysator."}, {"f": "Varför går en reaktion fortare vid högre temperatur?", "svar": "Partiklarna rör sig snabbare, krockar oftare och hårdare, och fler krockar leder till reaktion."}, {"f": "Vad är en katalysator?", "svar": "Ett ämne som gör att en reaktion går fortare utan att själv förbrukas."}, {"f": "Vad är skillnaden mellan exoterm och endoterm reaktion?", "svar": "Exoterm: energi avges och omgivningen blir varmare. Endoterm: energi tas upp och omgivningen blir kallare."}, {"f": "Ge ett exempel på en exoterm och en endoterm reaktion.", "svar": "Exoterm: förbränning. Endoterm: ättika och bikarbonat, där temperaturen sjunker."}]}], "begrepp": [{"term": "Endoterm", "forklaring": "Tar upp energi, omgivningen blir kallare."}, {"term": "Exoterm", "forklaring": "Avger energi, omgivningen blir varmare."}, {"term": "Katalysator", "forklaring": "Ämne som ökar hastigheten utan att förbrukas."}, {"term": "Koncentration", "forklaring": "Hur mycket ämne som finns i en viss volym."}, {"term": "Reaktionshastighet", "forklaring": "Hur fort en reaktion går."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Hastighet och energi", "text": ["<p>Varför brinner inte en trädbit av sig själv, trots att den kan reagera med syre och avge energi? Svaret har med aktiveringsenergi att göra.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/f_aktivering.png\" alt=\"Bild F4.6 Energidiagram för en exoterm reaktion (schematiskt): reaktionen behöver en energitopp, aktiveringsenergin, och en katalysator sänker toppen.\"><figcaption><strong>Bild F4.6</strong> Energidiagram för en exoterm reaktion (schematiskt): reaktionen behöver en energitopp, aktiveringsenergin, och en katalysator sänker toppen.</figcaption></figure>", "<p>För att en reaktion ska starta måste partiklarna krocka med tillräcklig energi. Den minsta energi som behövs kallas <strong>aktiveringsenergi</strong>. Därför behöver till exempel en tändsticka gnuggas eller ett bål tändas, även om reaktionen sedan avger mer energi än den kostade. En <strong>katalysator</strong> ger reaktionen en annan väg med lägre aktiveringsenergi, så att fler krockar räcker. Katalysatorn förbrukas inte.</p>", "<p>Energin i en reaktion kommer av att bindningar bryts (kräver energi) och nya bildas (avger energi). Är den energi som avges större än den som krävdes är reaktionen exoterm, annars endoterm. Hur mycket energi som totalt avges ändras inte av en katalysator, bara hur snabbt reaktionen går.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Rita ett energidiagram för en endoterm reaktion med och utan katalysator. Var hamnar utgångsämnena och produkterna, och vad förändras med katalysatorn?</div>"]}, {"ikon": "🧩", "titel": "Vad är en modell värd här?", "text": ["<p>Energidiagram och krockmodellen ger en enkel bild av varför reaktioner går och hur katalysatorer verkar. Verkligheten är mer komplicerad, men modellen räcker för att förutsäga hur temperatur och katalysator påverkar hastigheten.</p>"]}], "begrepp": [{"term": "Aktiveringsenergi", "forklaring": "Energi som krävs för att en reaktion ska starta."}, {"term": "Energidiagram", "forklaring": "Visar energin hos ämnena under en reaktion."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-4-2-l"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧪", "titel": "Labb 4.2 Massan bevaras", "text": ["<p><strong>Fråga:</strong> Ändras massan när ättika och bikarbonat reagerar?</p>", "<p>Du behöver: våg, två flaskor, ballong, ättika, bikarbonat, skyddsglasögon.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_labb2.png\" alt=\"\"></figure>", "<ol><li>Häll ättika i flaskan. Lägg bikarbonat i ballongen och trä på den.</li><li>Väg allt. Skriv ned massan.</li><li>Lyft ballongen så bikarbonatet faller ned. Väg igen.</li><li>Gör samma sak i en öppen flaska.</li></ol>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Försök</th><th>Massa före</th><th>Massa efter</th></tr><tr><td>Sluten flaska</td><td></td><td></td></tr><tr><td>Öppen flaska</td><td></td><td></td></tr></table></div>", "<p><strong>Säkerhet:</strong> Ha skyddsglasögon. Använd bara en tesked bikarbonat. Torka upp spill.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Slutet system: massan är lika. Öppen flaska: gasen lämnar och massan minskar.</div>"]}, {"ikon": "✏️", "titel": "Öva: Labb 4.2 Massan bevaras", "text": [], "ovningar": [{"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["gasen", "minskade", "oförändrad"], "meningar": ["I den slutna flaskan var massan §.", "I den öppna flaskan § massan.", "Det beror på att § lämnade flaskan."], "ratt": ["oförändrad", "minskade", "gasen"]}, {"typ": "skriv", "fraga": "Har några atomer försvunnit? Förklara.", "borja": "Nej, för att", "forslag": "Nej, för att atomerna finns kvar. Gasen följde med ut och har massa."}, {"typ": "skriv", "fraga": "Hur kan du göra mätningen bättre?", "borja": "Man kan", "forslag": "Man kan väga noggrannare och upprepa mätningen."}]}]}, "vanlig": {"sektioner": [{"ikon": "🧪", "titel": "Labb 4.2 Massan bevaras", "text": ["<p>Lavoisier vägde ämnen före och efter reaktioner. I det här försöket gör du något liknande: du låter ättika och bikarbonat reagera i en sluten och i en öppen flaska och väger.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade4/v_labb2.png\" alt=\"Bild 4.11 Sluten flaska med ballong och öppen flaska på våg (schematiskt, påhittade värden).\"><figcaption><strong>Bild 4.11</strong> Sluten flaska med ballong och öppen flaska på våg (schematiskt, påhittade värden).</figcaption></figure>", "<p><strong>Frågeställning:</strong> Ändras massan när ättika och bikarbonat reagerar, och spelar det någon roll om flaskan är öppen eller sluten?</p>", "<p><strong>Hypotes:</strong> Skriv vad du tror för båda fallen och motivera.</p>", "<p><strong>Material:</strong> våg (0,1 g), två plastflaskor eller koniska kolvar, ballong, ättika, bikarbonat (natriumvätekarbonat), mätcylinder, tesked, liten bägare, skyddsglasögon, hushållspapper.</p>"]}, {"ikon": "📖", "titel": "Gör så här", "text": ["<ol><li>Häll 50 ml ättika i flaskan. Lägg 1 tesked bikarbonat i ballongen och trä ballongen över flaskhalsen utan att hälla ned bikarbonatet.</li><li>Väg flaska, ballong och innehåll tillsammans. Skriv ned massan.</li><li>Lyft ballongen så bikarbonatet faller ned. Vänta tills det slutar bubbla och väg igen.</li><li>Upprepa med en öppen flaska. Ställ flaskan med ättikan och en bägare med bikarbonat på vågen, notera massan, häll ned bikarbonatet, ställ tillbaka bägaren och väg igen.</li></ol>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Bra att veta</span>Använd ballong, inte ett tätt lock: gasen kan annars ge så högt tryck att flaskan spricker.</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Försök</th><th>Massa före (g)</th><th>Massa efter (g)</th><th>Skillnad (g)</th></tr><tr><td>Sluten flaska</td><td></td><td></td><td></td></tr><tr><td>Öppen flaska</td><td></td><td></td><td></td></tr><tr><td>Eget försök</td><td></td><td></td><td></td></tr></table></div>", "<p class=\"not\">Säkerhet: Ha skyddsglasögon. Använd bara en tesked bikarbonat. Torka upp spill direkt. Ättika kan irritera ögonen, så skölj med vatten om du får stänk i ögat.</p>"]}, {"ikon": "❓", "titel": "Frågor", "text": ["<ol><li>Vad hände med massan i den slutna och i den öppna flaskan?</li><li>Förklara skillnaden med vad som hände med gasen. Har några atomer försvunnit?</li><li>Vilka felkällor finns? Hur kan du göra mätningen bättre?</li></ol>"]}], "begrepp": [{"term": "Massans bevarande", "forklaring": "Massan är lika stor före och efter."}, {"term": "Slutet system", "forklaring": "Inget ämne kommer in eller ut."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-4-s"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📌", "titel": "Sammanfattning", "text": ["<p>Läs orden och titta på bilderna. Du kan komma tillbaka hit när du läser.</p>", "<p>Här är allt det viktigaste i kapitlet. Läs det en gång till.</p>", "<ul class=\"viktigast\"><li>Molekyl: atomer delar elektroner (kovalent bindning). Exempel H₂O, CO₂, CH₄.</li></ul>", "<ul class=\"viktigast\"><li>Jon: laddad atom. Positiv och negativ jon drar till varandra: jonbindning.</li></ul>", "<ul class=\"viktigast\"><li>Salt har hög smältpunkt. Saltvatten leder ström, fast salt och sockervatten gör det inte.</li></ul>", "<ul class=\"viktigast\"><li>Kemisk reaktion: nya ämnen bildas. Utgångsämnen blir produkter.</li></ul>", "<ul class=\"viktigast\"><li>Balansera: lika många atomer av varje sort på båda sidor. Massan bevaras.</li></ul>", "<ul class=\"viktigast\"><li>Högre temperatur, koncentration, ytarea och katalysator ger snabbare reaktion.</li></ul>", "<ul class=\"viktigast\"><li>Exoterm: energi avges. Endoterm: energi tas upp.</li></ul>"]}], "begrepp": [{"term": "anjon", "forklaring": "en negativ jon"}, {"term": "balansera", "forklaring": "lika många atomer av varje sort på båda sidor"}, {"term": "elektrolyt", "forklaring": "ett ämne som leder ström när det är löst"}, {"term": "endoterm", "forklaring": "tar upp energi, det blir kallare"}, {"term": "exoterm", "forklaring": "avger energi, det blir varmare"}, {"term": "jon", "forklaring": "en laddad atom"}, {"term": "jonbindning", "forklaring": "positiva och negativa joner drar till varandra"}, {"term": "katalysator", "forklaring": "gör att en reaktion går fortare"}, {"term": "katjon", "forklaring": "en positiv jon"}, {"term": "kemisk bindning", "forklaring": "det som håller ihop atomer"}, {"term": "kemisk förening", "forklaring": "ett ämne med atomer av olika grundämnen som sitter ihop"}, {"term": "kemisk reaktion", "forklaring": "nya ämnen bildas"}, {"term": "kovalent bindning", "forklaring": "atomer delar elektronpar"}, {"term": "molekyl", "forklaring": "atomer som delar elektroner och sitter ihop"}, {"term": "produkt", "forklaring": "ämne som bildas"}, {"term": "salt", "forklaring": "en jonförening, till exempel bordssalt"}, {"term": "smältpunkt", "forklaring": "temperaturen då ett ämne smälter"}, {"term": "utgångsämne", "forklaring": "ämne som reagerar"}]}, "vanlig": {"sektioner": [{"ikon": "📌", "titel": "Sammanfattning", "text": ["<ul><li>En <strong>kemisk förening</strong> är ett ämne där atomer av olika grundämnen är bundna till varandra med <strong>kemiska bindningar</strong>.</li><li>I en <strong>kovalent bindning</strong> delar atomer elektronpar, oftast mellan icke-metaller. Atomerna bildar <strong>molekyler</strong>, som H₂O, CO₂ och CH₄. Molekylformeln visar vilka atomer och hur många.</li><li>En <strong>jon</strong> är en laddad atom. En <strong>katjon</strong> är positiv (avger elektroner), en <strong>anjon</strong> är negativ (tar upp elektroner). Ex: Na⁺ och Cl⁻.</li><li><strong>Jonbindning</strong> är attraktionen mellan positiva och negativa joner. Metall plus icke-metall ger en jonförening (<strong>salt</strong>) med joner i ett <strong>kristallgitter</strong>.</li><li>Jonföreningar har höga smältpunkter (NaCl ungefär 800 °C), molekylföreningar ofta låga. En jonförening leder ström när den är löst eller smält (<strong>elektrolyt</strong>) men inte som fast ämne.</li><li>I en <strong>kemisk reaktion</strong> bildas nya ämnen. <strong>Utgångsämnen</strong> reagerar och <strong>produkter</strong> bildas. Tecken: gas, temperaturförändring, färgförändring, fast ämne, ljus eller lukt. En fysikalisk förändring ger inga nya ämnen.</li><li>En <strong>reaktionsformel</strong> måste <strong>balanseras</strong>: lika många atomer av varje sort på båda sidor. Man sätter koefficienter framför formlerna och ändrar aldrig talen i formlerna.</li><li><strong>Massan bevaras</strong> i ett slutet system (Lavoisier). I en öppen behållare kan massan minska om en gas lämnar.</li><li><strong>Reaktionshastigheten</strong> ökar med temperatur, koncentration, ytarea och katalysator. Reaktioner kan vara <strong>exoterma</strong> (avger energi) eller <strong>endoterma</strong> (tar upp energi).</li></ul>"]}], "begrepp": [{"term": "Anjon", "forklaring": "Negativ jon."}, {"term": "Balansera", "forklaring": "Göra så att lika många atomer av varje sort finns på båda sidor."}, {"term": "Elektrolyt", "forklaring": "Ämne som leder ström när det är löst eller smält."}, {"term": "Endoterm", "forklaring": "Tar upp energi."}, {"term": "Exoterm", "forklaring": "Avger energi."}, {"term": "Fysikalisk förändring", "forklaring": "Samma ämne byter tillstånd eller form."}, {"term": "Jon", "forklaring": "Laddad atom."}, {"term": "Jonbindning", "forklaring": "Attraktion mellan positiva och negativa joner."}, {"term": "Jonförening", "forklaring": "Förening av joner, ofta en metall och en icke-metall."}, {"term": "Katalysator", "forklaring": "Ämne som ökar reaktionshastigheten utan att förbrukas."}, {"term": "Katjon", "forklaring": "Positiv jon."}, {"term": "Kemisk bindning", "forklaring": "Det som håller ihop atomer."}, {"term": "Kemisk förening", "forklaring": "Ämne med atomer av olika grundämnen bundna till varandra."}, {"term": "Kemisk reaktion", "forklaring": "Förändring där nya ämnen bildas."}, {"term": "Koefficient", "forklaring": "Talet framför en formel i en reaktionsformel."}, {"term": "Kovalent bindning", "forklaring": "Bindning där atomer delar elektronpar."}, {"term": "Kristallgitter", "forklaring": "Regelbundet mönster av joner."}, {"term": "Massans bevarande", "forklaring": "Massan är lika stor före och efter en reaktion i ett slutet system."}, {"term": "Molekyl", "forklaring": "Atomer som hålls ihop av kovalenta bindningar."}, {"term": "Molekylformel", "forklaring": "Visar vilka atomer och hur många som finns i molekylen."}, {"term": "Produkt", "forklaring": "Ämne som bildas i en reaktion."}, {"term": "Reaktionsformel", "forklaring": "Reaktion skriven med formler."}, {"term": "Reaktionshastighet", "forklaring": "Hur fort en reaktion går."}, {"term": "Salt", "forklaring": "Jonförening av en metall och en icke-metall."}, {"term": "Utgångsämne", "forklaring": "Ämne som reagerar. Kallas även reaktant."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-4-t"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📝", "titel": "Testa dig själv", "text": ["Nu får du visa vad du har lärt dig. Du kan titta i kapitlet om du vill."], "ovningar": [{"typ": "ringa", "fraga": "Vad kallas en positiv jon?", "val": ["Katjon", "Anjon", "Molekyl"], "ratt": 0}, {"typ": "streck", "fraga": "Dra streck till rätt förklaring.", "vanster": ["Molekyl", "Jonbindning", "Balansera", "Katalysator"], "hoger": ["+ och − drar till varandra", "atomer delar elektroner", "lika många atomer på båda sidor", "ökar hastigheten"], "ratt": ["atomer delar elektroner", "+ och − drar till varandra", "lika många atomer på båda sidor", "ökar hastigheten"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Fast salt leder ström.", "Saltvatten leder ström.", "Is som smälter är en kemisk reaktion.", "Atomer försvinner inte i en reaktion.", "Förbränning avger energi.", "H₂O har två syreatomer."], "ratt": [false, true, false, true, true, false]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["exoterm", "molekyl", "produkter"], "meningar": ["Atomer som delar elektroner bildar en §.", "Ämnena som bildas kallas §.", "En reaktion som avger energi är §."], "ratt": ["molekyl", "produkter", "exoterm"]}, {"typ": "siffror", "fraga": "Sätt i ordning. Skriv 1, 2, 3 och 4.", "delar": ["Balansera formeln", "Skriv formlerna", "Kontrollera", "Räkna atomerna"], "ratt": [3, 1, 4, 2]}, {"typ": "skriv", "fraga": "Balansera: H₂ + Cl₂ → HCl. Skriv med tal framför.", "borja": "Svar:", "forslag": "H₂ + Cl₂ → 2 HCl"}, {"typ": "skriv", "fraga": "Varför smälter salt vid högre temperatur än vatten fryser?", "borja": "Det beror på att", "forslag": "Jonerna i salt hålls ihop av starka krafter, så det krävs mycket energi för att smälta det."}, {"typ": "skriv", "fraga": "Nämn ett tecken på kemisk reaktion och en sak som påverkar hastigheten.", "borja": "Tecken:", "forslag": "Gasbildning är ett tecken. Temperaturen påverkar hastigheten."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Del A · Välj ett alternativ", "text": ["Uppgifterna liknar uppgifterna på nationella prov i kemi. Personer, annonser och mätvärden är påhittade."], "ovningar": [{"typ": "ringa", "fraga": "Vad kallas en positivt laddad jon?", "val": ["Anjon", "Katjon", "Molekyl", "Neutron"], "ratt": 1}, {"typ": "ringa", "fraga": "Vilken formel visar koldioxid?", "val": ["CO", "C₂O", "CO₂", "Co"], "ratt": 2}, {"typ": "ringa", "fraga": "Vilket ämne leder elektrisk ström när det är löst i vatten?", "val": ["Socker", "Bordssalt", "Syre", "Vätgas"], "ratt": 1}, {"typ": "ringa", "fraga": "Vilket är ett tecken på att en kemisk reaktion har skett?", "val": ["Is smälter", "Socker löses i vatten", "Det bildas bubblor av en ny gas när två ämnen blandas", "Vatten kokar"], "ratt": 2}]}, {"ikon": "📖", "titel": "Del B · Svara kort", "text": [], "ovningar": [{"typ": "fri", "fraga": "Förklara skillnaden mellan en kovalent bindning och en jonbindning.", "forslag": "I en kovalent bindning delar två atomer elektronpar, oftast mellan icke-metaller, och det ger molekyler. I en jonbindning flyttar en eller flera elektroner från en atom (oftast en metall) till en annan (oftast en icke-metall), så att positiva och negativa joner bildas som dras till varandra."}, {"typ": "fri", "fraga": "Förklara vad som menas med att en reaktion är exoterm, och ge ett exempel.", "forslag": "Exoterm betyder att energi avges till omgivningen, som blir varmare. Exempel: förbränning, till exempel när metan brinner."}]}, {"ikon": "📖", "titel": "Del C · Tolka resultat och förklara", "text": [], "ovningar": [{"typ": "fri", "fraga": "Tre påhittade ämnen har undersökts. Värdena är påhittade men liknar riktiga ämnen.<br><div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Ämne</th><th>Smältpunkt</th><th>Leder fast ämne ström?</th><th>Leder löst i vatten ström?</th></tr><tr><td>X</td><td>805 °C</td><td>Nej</td><td>Ja</td></tr><tr><td>Y</td><td>−78 °C</td><td>Nej</td><td>Nej</td></tr><tr><td>Z</td><td>660 °C</td><td>Ja</td><td>Löser sig inte</td></tr></table></div>a) Vilket ämne är troligen en jonförening, vilket en molekylförening och vilket en metall? Motivera med uppgifterna.<br>b) Förklara varför ämne X leder ström löst i vatten men inte som fast ämne.<br>c) Vad säger smältpunkten hos ämne Y om krafterna mellan dess partiklar?", "forslag": "a) X är troligen en jonförening (hög smältpunkt, leder löst men inte fast). Y är troligen en molekylförening (låg smältpunkt, leder inte). Z är troligen en metall (leder som fast ämne). b) I fast ämne sitter jonerna fast i gittret. När X löses i vatten kan jonerna röra sig fritt och bära strömmen. c) Den låga smältpunkten visar att krafterna mellan partiklarna är svaga, så det krävs lite energi för att få dem att röra sig."}, {"typ": "fri", "fraga": "a) Balansera H₂ + Cl₂ → HCl och 2 Mg + O₂ → MgO (sätt koefficienter). b) Förklara varför man sätter tal framför formlerna men aldrig ändrar talen inne i formlerna.", "forslag": "a) H₂ + Cl₂ → 2 HCl. 2 Mg + O₂ → 2 MgO. b) Koefficienterna visar hur många molekyler som reagerar och ändrar inte vilket ämne det är. Ändrar man talen inne i formeln byter man ut ämnet, till exempel blir H₂O₂ ett annat ämne än H₂O."}]}, {"ikon": "📖", "titel": "Del D · Resonera och ta ställning", "text": [], "ovningar": [{"typ": "fri", "fraga": "En elev blandar ättika och bikarbonat i en öppen flaska på en våg och ser att massan minskar. Hon säger: ”Då försvann atomer!” Bedöm påståendet, och förklara hur man kan göra försöket så att massan inte minskar.", "forslag": "Påståendet är fel. Atomer försvinner inte i kemiska reaktioner. När ättika och bikarbonat reagerar bildas koldioxid, en gas, som lämnar den öppna flaskan och tar sin massa med sig, så vågen visar mindre. Massan hos allt tillsammans, flaska, innehåll och gas, är oförändrad. Genom att låta reaktionen ske i en sluten flaska eller i en flaska med ballong, så att gasen stannar kvar, visar vågen samma massa före och efter. (Obs: ballongen ger en liten uppdrift, så vågen kan visa någon tiondels gram mindre. Det är en mätosäkerhet.)"}, {"typ": "fri", "fraga": "Förklara med natrium och klor hur en jonbindning bildas (valenselektroner, joner och laddning). Förklara också varför fast bordssalt inte leder ström men saltlösning gör det.", "forslag": "Natrium har en valenselektron (2, 8, 1) och avger den lätt. Då får atomen 2, 8, men fortfarande 11 protoner, så den blir en positiv natriumjon, Na⁺. Klor har sju valenselektroner (2, 8, 7) och tar upp en elektron, får 2, 8, 8 och laddningen −1: Cl⁻. De motsatta laddningarna drar mot varandra, och det är jonbindningen. I fast salt sitter jonerna fast i gittret och kan inte röra sig, så ingen laddning transporteras. I saltlösning har vattnet dragit loss jonerna, som kan röra sig och bära strömmen."}]}, {"ikon": "📖", "titel": "Del E · Förutsäg och värdera", "text": [], "ovningar": [{"typ": "fri", "fraga": "Ett kylpaket blir kallt när man trycker så att två ämnen blandas. Förutsäg om reaktionen är exoterm eller endoterm, förklara energiomsättningen med bindningar och diskutera hur du kan kontrollera din slutsats.", "forslag": "Öppet svar. Ett välutvecklat svar: kylpaketet blir kallt, så energi tas upp från omgivningen: reaktionen är endoterm. Det beror på att det krävs mer energi för att bryta bindningarna i utgångsämnena än som avges när nya bildas. Slutsatsen kan kontrolleras genom att mäta temperaturen med termometer före och efter, upprepa försöket, jämföra med en kontroll (bara vatten) och se om temperaturen sjunker varje gång. Det kan också vara en lösning av ett salt som tar upp värme när det löses, vilket visar att man behöver mer än en iakttagelse."}, {"typ": "fri", "fraga": "Bedöm påståendet ”En kemisk reaktion kan ändra massan eftersom nya atomer bildas”. Använd en reaktionsformel och förklara även hur temperatur och katalysator kan påverka hur fort reaktionen går.", "forslag": "Påståendet är fel. Atomer skapas inte i kemiska reaktioner, de byter partner, så massan bevaras i ett slutet system. Exempel: 2 H₂ + O₂ → 2 H₂O har 4 H och 2 O på båda sidor. Högre temperatur gör att partiklarna krockar oftare och hårdare, så reaktionen går fortare. En katalysator ökar hastigheten utan att förbrukas, och ändrar inte massan eller vilka produkter som bildas i huvudsak."}]}]}, "fordjupning": {"sektioner": [{"ikon": "💭", "titel": "Resonera och ta ställning", "text": ["Uppgifterna liknar de svåraste uppgifterna på nationella prov. Personer, rubriker och mätvärden är påhittade. Svara utförligt och resonera i flera led."], "ovningar": [{"typ": "fri", "fraga": "Magnesium står i grupp 2 och klor i grupp 17. a) Förklara vilka joner de bildar och varför. b) Förklara varför formeln för magnesiumklorid är MgCl₂. c) Värdera regeln att gruppnumret bestämmer jonens laddning: när fungerar den och när inte?", "forslag": "a) Magnesium har 2 valenselektroner och avger dem: Mg²⁺. Klor har 7 och tar upp en: Cl⁻. Båda får fullt yttersta skal. b) Laddningen måste bli noll: Mg²⁺ behöver två Cl⁻, så MgCl₂. c) Regeln fungerar bra för grupp 1, 2, 13 och för 16 och 17. Den fungerar sämre för övergångsmetaller som järn, som kan bilda joner med olika laddning. Det är en förenklad modell."}, {"typ": "fri", "fraga": "En elev säger: ”Metaller leder ström eftersom de är jonföreningar.” a) Förklara hur metaller leder ström. b) Bedöm påståendet. c) Förklara varför en jonkristall är spröd medan en metall går att böja.", "forslag": "a) Metaller leder ström eftersom de har fria elektroner som kan röra sig mellan metalljonerna. b) Påståendet är fel: metaller är inte jonföreningar. De består av positiva joner i ett hav av fria elektroner (metallbindning). Jonföreningar leder bara löst eller smält. c) I en jonkristall hamnar likladdade joner intill varandra om ett lager förskjuts, så de stöter bort varandra och kristallen spricker. I en metall kan jonerna glida förbi varandra utan att bindningen bryts."}, {"typ": "fri", "fraga": "Kloratomen drar hårdare i elektronerna än väteatomen (H 2,1, Cl 3,0). a) Beräkna skillnaden och avgör vilken sorts bindning H–Cl är. b) Förklara vad δ+ och δ− betyder i molekylen. c) Förklara varför CO₂ är opolär fast C=O-bindningarna är polära.", "forslag": "a) Skillnaden är 3,0 − 2,1 = 0,9, vilket ger en polär kovalent bindning. b) δ− betyder en liten negativ laddning (på Cl, som drar hårdare), δ+ en liten positiv (på H). c) CO₂ är rak. De två polära bindningarna drar åt motsatta håll och tar ut varandra, så molekylen som helhet är opolär."}, {"typ": "fri", "fraga": "Det börjar brinna i en stekpanna med olja. a) Förklara med brandtriangeln hur du ska släcka och vad du inte ska göra. b) Skriv och balansera förbränning av etanol (C₂H₅OH + O₂ → CO₂ + H₂O). c) Förklara varför det är farligt att elda i ett rum med dålig ventilation.", "forslag": "a) Ta bort syre genom att lägga ett lock eller en brandfilt över, och stäng av värmen. Använd aldrig vatten, eftersom det kan få fettet att stänka kraftigt. b) C₂H₅OH + 3 O₂ → 2 CO₂ + 3 H₂O. På båda sidor: 2 C, 6 H, 7 O. c) Vid brist på syre blir förbränningen ofullständig och kolmonoxid bildas. Det är giftigt och luktfritt."}, {"typ": "fri", "fraga": "En segelbåt har skrov av stål. a) Förklara hur stål rostar. b) Jämför tre sätt att skydda skrovet (färg, zink, offeranod) och värdera dem. c) Förklara varför en offeranod av zink skyddar men en av koppar inte gör det.", "forslag": "a) Stål (järn) reagerar med syre och vatten och bildar rost (järnoxid). b) Färg: billigt men måste underhållas och släpper in vatten om det repas. Zink (galvanisering): skyddar även vid repor eftersom zink är mer reaktiv. Offeranod: bra för föremål som sitter i vatten, kräver byte. Ett välutvecklat svar väger kostnad, hållbarhet och miljö. c) Zink är mer reaktiv än järn och rostar i stället. Koppar är mindre reaktiv än järn och skulle få järnet att rosta snabbare."}, {"typ": "fri", "fraga": "En fabrik ska göra en reaktion snabbare. a) Förklara hur högre temperatur, större ytarea och en katalysator var för sig ökar hastigheten. b) Rita ett energidiagram för en exoterm reaktion och markera aktiveringsenergin med och utan katalysator. c) En kollega säger att katalysatorn gör att reaktionen avger mer energi. Värdera påståendet.", "forslag": "a) Högre temperatur: partiklarna rör sig snabbare och krockar oftare och hårdare, så fler når aktiveringsenergin. Större ytarea: fler partiklar kan krocka. Katalysator: en väg med lägre aktiveringsenergi. b) Ett diagram med utgångsämnen högt och produkter lågt, en energitopp över utgångsämnena, och en lägre topp med katalysator. c) Påståendet är fel. En katalysator ändrar bara hastigheten, inte hur mycket energi som totalt avges."}]}]}}, nivaStandard: "vanlig"};
